def main(api):
    c = {}
    for m in api.recall():
        if m["key"] == "method": c = api.recall("method")["value"]
    if not c: c = {"phase":"survey", "log":[], "tests":0}
    c.pop("cache",None)
    def save(): api.checkpoint("method", c)
    def note(kind, data): c["log"] = (c["log"] + [{"kind":kind, "data":str(data)[:512]}])[-8:]; api.note(str({"kind":kind, "data":data})); save()
    def result(ok, gap): save(); return {"completion_proposed":bool(ok), "evidence":{"phase":c["phase"], "gap":gap, "measurements":c["log"], "retention":c.get("retention"), "final":c.get("final"), "budgets":api.state()["budgets"]}}
    def ask(q, fields, context=None):
        if api.state()["budgets"]["gpt_remaining"] < 1: note("gap", "No observation review budget"); return None
        r = api.review(q, context=context, fields=fields)
        if r["measurement_errors"]: note("measurement_errors", r["measurement_errors"])
        return None if r["status"] == "stop" else r
    pixel = {"type":"array","items":{"type":"number"},"minItems":2,"maxItems":2}; polygon = {"type":["array","null"],"items":pixel,"minItems":3,"maxItems":16}
    patch_fields = {"identity":["same","ambiguous","absent"],"definition":{"type":"string","maxLength":240},"camera":["agentview","robot0_eye_in_hand"],"polygon":polygon}; questions = {}
    for axis in ["x","y","z","rx","ry","rz"]: questions[axis] = {"type":"choice","instructions":"For world axis "+axis+", use state.processed_features.axes."+axis+".goal_relation. Increase means positive, decrease negative, within_tolerance hold. Do not infer object success.","criteria":{"negative":"decrease this world component","hold":"this component is within tolerance","positive":"increase this world component"}}
    questions["gripper"] = {"type":"choice","instructions":"Execute state.processed_features.objective.gripper exactly: open, close, or keep. Keep never reopens a held item.","criteria":{"open":"requested open","close":"requested close","keep":"requested keep"}}
    def numeric(d): return {k:np.asarray(v).tolist() for k,v in d.items()}
    def plane(r, name):
        if r is None or name not in r["regions"]: return None
        a = np.asarray(r["regions"][name]["world_m"], dtype=float)
        if len(a) < 6: return None
        try: p = numeric(geo.plane(a))
        except (ValueError, RuntimeError) as e: note("fit_rejected", str(e)); return None
        if p["rms_m"] > 0.003 or min(p["in_plane_spread_m"]) <= max(0.0007, 2*p["rms_m"]): note("plane_inadequate", p); return None
        return p
    def rays(camera, pixels, p):
        if pixels is None: return None
        out = []
        for uv in pixels:
            try: out.append(api.plane_point(camera, uv, p["coefficients"])["world_m"])
            except (ValueError, RuntimeError) as e: note("ray_failed", str(e)); return None
        return np.asarray(out)
    bowl_request = "Measure rim0 through rim7 as eight spread visible points on the INNER opening lip of the intended bowl, not its outer silhouette; also floor on its visible interior support surface. Prefer the other camera for missing measurements."
    def bowl(r):
        if r is None or "floor" not in r["points"]: return None
        pts = [r["points"]["rim"+str(i)]["world_m"] for i in range(8) if "rim"+str(i) in r["points"]]
        if len(pts) < 5: return None
        try: f = numeric(geo.circle_xy(pts)); p = numeric(geo.plane(pts))
        except (ValueError, RuntimeError) as e: note("rim_fit_failed", str(e)); return None
        u = max(0.001, f["max_radial_error_m"], p["rms_m"]); floor = r["points"]["floor"]["world_m"]
        if f["largest_angular_gap_rad"] >= math.pi or p["coefficients"][2] < 0.97 or u > 0.15*f["radius_m"] or floor[2] >= p["center_world_m"][2]-u: note("rim_inadequate", {"fit":f,"plane":p,"floor":floor}); return None
        return {"xy":f["center_xy_m"],"radius":f["radius_m"],"z":p["center_world_m"][2],"floor":floor,"u":u,"frame":r["frame_id"]}
    def newref(r=None, envelope=None):
        if r is None:
            r = ask("Identify a currently visible rigid textured patch of the SAME requested movable item, regardless of old corner indices. Return identity, a persistent physical definition of a distinctive interior print feature, its camera, and polygon around texture on that body only (null if unavailable). Measure named point mark at that defined feature. This initializes a NEW local motion reference, not an old-shape registration.", patch_fields, {"old_reference":c.get("ref"),"phase":c["phase"]})
        if r is None or r["parameters"]["identity"] != "same" or "mark" not in r["points"]: return False
        p = r["parameters"]; ref = {"definition":p["definition"],"mark":r["points"]["mark"]["world_m"],"mark_observation":r["points"]["mark"],"frame":r["frame_id"],"camera":p["camera"],"polygon":p["polygon"],"shape":envelope,"tracker":None}
        if p["polygon"] is not None:
            try:
                t = api.track_init(p["camera"], p["polygon"])
                if t["frame_id"] == r["frame_id"]: ref["tracker"] = {key:t[key] for key in ["handle","frame_id","camera","method_number","source_sha256"]}
            except RuntimeError as e: note("patch_initialization", str(e))
        c["ref"] = ref; c["ref_serial"] = c.get("ref_serial",0)+1; c.pop("cache",None); save(); return True
    def remember(w, full): c["cache"] = {"frame":api.state()["frame_id"],"serial":c.get("ref_serial",0),"full":full,"witness":w}; save(); return w
    def witness(allow_landmark=True):
        cache = c.get("cache")
        if cache is not None and cache["frame"] == api.state()["frame_id"] and cache["serial"] == c.get("ref_serial",0) and (cache["full"] or not allow_landmark): return cache["witness"]
        ref = c.get("ref")
        if ref is None: return None
        if ref["tracker"] is not None:
            t = api.track_update(ref["tracker"]["handle"])
            if t["status"] == "tracked":
                spread = sorted(np.asarray(t["inlier_spread_m"]).reshape(-1).tolist()); s = spread[-2] if len(spread) > 1 else spread[0]; u = max(0.0007, t["rms_m"], t["uncertainty_floor_m"])
                if t["reference_frame_id"] == ref["tracker"]["frame_id"] and t["inliers"] >= 12 and t["inliers"]/max(1,t["matches"]) >= 0.55 and s > 2*u:
                    T = np.asarray(t["transform_initial_world_to_current_world"]); center = np.asarray(t["reference_patch_centroid_world_m"]); factor = 1+float(np.linalg.norm(np.asarray(ref["mark"])-center))/s; noise = u*factor; shared = 0.0007*factor; local_u = noise+shared; shape = None
                    if ref["shape"] is not None: old = np.asarray(ref["shape"]["points"]); shape = {"points":geo.transform(old,T).tolist(),"u":ref["shape"]["u"]+u*(1+float(np.max(np.linalg.norm(old-center,axis=1)))/s)}
                    return remember({"point":geo.transform([ref["mark"]],T)[0].tolist(),"u":local_u,"shape":shape,"frame":t["frame_id"],"source":"rigid_patch","noise":noise,"shared":shared,"reference_id":c.get("ref_serial",0)},True)
            note("tracker_unknown_or_inadequate", {"frame":t["frame_id"],"status":t["status"]})
        if not allow_landmark: return remember(None,False)
        r = ask("Locate named point mark at the EXACT physical feature in reference.definition, not a screen-relative replacement. Return body=same/ambiguous/absent separately from correspondence=same/ambiguous/not_visible. Use either camera and an interior depth-valid sample. Historical projections are not detections.", {"body":["same","ambiguous","absent"],"correspondence":["same","ambiguous","not_visible"]}, ref)
        if r is not None and r["parameters"]["body"] == "same" and r["parameters"]["correspondence"] == "same" and "mark" in r["points"]: return remember({"point":r["points"]["mark"]["world_m"],"u":0.002,"shape":None,"frame":r["frame_id"],"source":"physical_landmark","noise":0.0015,"shared":0.0005,"reference_id":c.get("ref_serial",0)},True)
        return remember(None,True)
    def envelope(use_reference=True):
        w = witness(False) if use_reference else None
        if w is not None and w["shape"] is not None: return w["shape"]
        fields = dict(patch_fields); fields.update({"edge_labels":["long_short","ambiguous","unknown"],"rays":{"type":["array","null"],"items":pixel,"minItems":3,"maxItems":3}})
        for k in range(2):
            r = ask("Recover ONLY the current box envelope. Request tight region top on visible planar top-face interior, explicit camera/box/stride=4. Return rays=[a visible physical top vertex, a point along its inward LONG incident edge, a point along its inward SHORT incident edge], in camera pixels. Edge points need not be other corners. edge_labels=ambiguous retains BOTH length assignments; unknown means no usable two-edge evidence. Reject hidden/invented vertices. Also supply identity, definition, camera, polygon and measured mark for a new local patch as previously specified. Try the other view on this bounded retry.", fields, {"dimensions":c["g"]["dimensions"],"attempt":k,"previous_reference":c.get("ref")})
            p = plane(r,"top")
            if p is None or r["parameters"]["identity"] != "same" or r["parameters"]["edge_labels"] == "unknown": continue
            a = rays(r["parameters"]["camera"],r["parameters"]["rays"],p)
            if a is None or p["coefficients"][2] < 0.96: continue
            d,e = a[1]-a[0],a[2]-a[0]; ld,le = float(np.linalg.norm(d)),float(np.linalg.norm(e)); u = max(0.001,p["rms_m"]); L,W,h = c["g"]["dimensions"]
            if min(ld,le) <= 3*u or abs(float(np.dot(d,e)))/max(ld*le,0.0000001) > 0.15: continue
            d,e = d/ld,e/le; sizes = [(L,W)] if r["parameters"]["edge_labels"] == "long_short" else [(L,W),(W,L)]; pts = []
            for l,b in sizes:
                if ld > l+2*u or le > b+2*u: continue
                top = np.asarray([a[0],a[0]+l*d,a[0]+b*e,a[0]+l*d+b*e]); pts.extend(top.tolist()); pts.extend((top-np.asarray(p["coefficients"][:3])*h).tolist())
            if not pts: continue
            env = {"points":pts,"u":u*(1+L/ld+W/le)}; newref(r,env); note("current_envelope", {"u":env["u"],"hypotheses":len(sizes),"frame":r["frame_id"]}); return env
        return None
    def difference_u(b,a,old,new):
        if b.get("reference_id") != a.get("reference_id") or b["source"] != a["source"]: return b["u"]+a["u"]
        angle_effect = float(np.linalg.norm(geo.rotation(new["tcp_quaternion_xyzw"])-geo.rotation(old["tcp_quaternion_xyzw"]),2))
        return b.get("noise",b["u"])+a.get("noise",a["u"])+max(b.get("shared",0),a.get("shared",0))*angle_effect
    def footprint(points): candidates = [np.mean(points[:,:2],axis=0),(np.min(points[:,:2],axis=0)+np.max(points[:,:2],axis=0))/2]; scores = [float(np.max(np.linalg.norm(points[:,:2]-v,axis=1))) for v in candidates]; k = 0 if scores[0] <= scores[1] else 1; return candidates[k],scores[k]
    def projections(points):
        out = {}
        for name in ["agentview","robot0_eye_in_hand"]:
            cam = api.camera(name); xyz = geo.transform(points,np.linalg.inv(np.asarray(cam["camera_to_world_opencv"]))); uvw = xyz @ np.asarray(cam["K"]).T
            out[name] = {"frame":cam["frame_id"],"planned_pixels":[(uvw[i,:2]/uvw[i,2]).tolist() if xyz[i,2]>0 else None for i in range(len(xyz))]}
        return out
    def move(target, quaternion, gripper, tag, carry=False, tol=0.003):
        target = np.asarray(target); tol = float(tol); views = 0
        for leg in range(24):
            s = api.state(); pad = np.asarray(geo.pad_position(s)); delta = target-pad; dist = float(np.linalg.norm(delta)); angle = math.acos(max(-1.0,min(1.0,(float(np.trace(geo.rotation(quaternion) @ geo.rotation(s["tcp_quaternion_xyzw"]).T))-1)/2)))
            if dist <= tol and angle <= 0.04: return True
            reserve = 2 if c["phase"] == "released" else 3 if tag == "low release above rim; no finger insertion" else 4; control_reserve = 3 if c["phase"] == "released" else 20
            if s["budgets"]["gpt_remaining"] <= reserve or s["budgets"]["jev_remaining"] < control_reserve+2 or s["budgets"]["native_steps_remaining"] < 3*(control_reserve+2): note("resource_reserve", tag); return False
            b = witness() if carry else None
            if carry and b is None:
                if not held(): return False
                continue
            nxt = pad + delta*min(1.0,0.08/max(dist,0.000001))
            load = b if b is not None else c.get("test",{}).get("before") if c["phase"] in ["testing","held"] else None
            bound = None if load is None else {"anchor":load["point"],"radius_m":float(np.linalg.norm(c["g"]["dimensions"]))+(0.04 if not carry else 0),"envelope":load["shape"],"reference_frame":load["frame"],"source":"Current anchor for transfer; historical pre-test anchor with expanded trial bound otherwise. Not a clearance certificate."}
            r = ask("Review ONLY the proposed next local segment, not an entire future corridor. obstruction=external only for a visible unintended object intersection; none_visible is NOT certified clearance; unknown means not assessable. visibility distinguishes observed, partial, self_occluded, unobserved. local=supported requires visible local surfaces plus the stated short-horizon geometry to justify a bounded step; otherwise unknown/unsupported. change describes unexpected motion contradicting stationary references (carried-item motion is expected). view_up=yes only if a 0.02 m upward observation move of hand and any load is locally supported; otherwise no/unknown. Projected planned pixels are calibration-derived action annotations, not object detections. Do not confuse a changed camera with body motion.", {"obstruction":["external","none_visible","unknown"],"visibility":["observed","partial","self_occluded","unobserved"],"local":["supported","unsupported","unknown"],"change":["consistent","item_moved","container_moved","unknown"],"view_up":["yes","no","unknown"]}, {"tag":tag,"pad":pad.tolist(),"next_pad":nxt.tolist(),"quaternion":quaternion,"carrying":carry or c["phase"] in ["testing","held","releasing"],"local_load_bound":bound,"planned_pad_pixels":projections([pad.tolist(),nxt.tolist()]),"geometry":c.get("g"),"stationary_prior":"Table and bowl retained only absent contact or contradictory observations; item envelope is not retained through grasp contact.","phase":c["phase"]})
            if r is None: return False
            p = r["parameters"]
            if p["change"] == "container_moved" or (p["change"] == "item_moved" and c["phase"] in ["survey","approach"]): note("observed_route_contradiction", p); return False
            if p["local"] != "supported" or p["obstruction"] != "none_visible":
                if p["view_up"] != "yes" or views >= (3 if p["obstruction"] == "external" else 1): note("local_evidence_gap", p); return False
                nxt = pad + np.asarray([0,0,0.02]); views += 1
            elif p["visibility"] == "unobserved": nxt = pad + delta*min(1.0,0.04/max(dist,0.000001))
            c["intent"] = {"tag":tag,"target":nxt.tolist(),"gripper":gripper,"frame":s["frame_id"]}; save(); limit = min(16,s["budgets"]["jev_remaining"]-control_reserve,s["budgets"]["native_steps_remaining"]//3-control_reserve)
            r = api.drive(nxt.tolist(),quaternion,gripper,questions,features={"phase":tag,"local_review":p,"tolerance_m":tol},tool_point="pad_center",max_calls=int(limit),translation_limit=0.02,rotation_limit=0.08,steps=3,position_tolerance=tol,rotation_tolerance=0.04); after = api.state()
            c["last_motion"] = {"status":r["status"],"frame":r["frame_id"],"pad":geo.pad_position(after).tolist(),"position_error_m":r["position_error_m"]}; save()
            if r["status"] == "stalled" or r["status"] not in ["reached","moved","lease_exhausted"]: note("motion_failed", c["last_motion"]); return False
            if float(np.linalg.norm(np.asarray(geo.pad_position(after))-pad)) < 0.0005 and dist > tol: note("no_progress", c["last_motion"]); return False
            if carry:
                a = witness()
                if a is None:
                    if not held(): return False
                else:
                    err = float(geo.attachment_error([b["point"]],[a["point"]],s,after)); allowance = max(0.003,difference_u(b,a,s,after)); note("transfer_effect", {"attachment_error":err,"heuristic_allowance":allowance,"frame":a["frame"]})
                    if err > allowance and not held(): return False
        note("route_bound", {"tag":tag,"target":target.tolist()}); return False
    def held():
        for attempt in range(3):
            test = c.get("test"); renew = test is not None and test["pending"]
            if test is not None and test["pending"]:
                a = witness(); s = api.state(); b = test["before"]; old = test["robot"]; hand = float(np.linalg.norm(np.asarray(s["tcp_position_world_m"])-old["tcp_position_world_m"])); test["pending"] = False; save()
                if a is not None and hand >= 0.015:
                    err = float(geo.attachment_error([b["point"]],[a["point"]],old,s)); up = a["point"][2]-b["point"][2]; u = difference_u(b,a,old,s); ev = {"hand_motion":hand,"observed_up":up,"attachment_error":err,"heuristic_uncertainty":u,"frame":a["frame"]}; note("retention_trial",ev)
                    if u < 0.4*hand and err <= max(0.003,u) and up > max(0.01,2*u): c["retention"] = ev; c["phase"] = "held"; save(); return True
                    if u < 0.2*hand and (up < 0.2*hand or err > 0.65*hand+u): note("retention_contradicted",ev); return False
            if attempt == 2 or c["tests"] >= 4: return False
            b = None if renew else witness()
