            if b is None: continue
            s = api.state(); c["tests"] += 1; c["test"] = {"pending":True,"before":b,"robot":s}; save()
            if not move((np.asarray(geo.pad_position(s))+[0,0,0.03]).tolist(),s["tcp_quaternion_xyzw"],"keep","local upward retention experiment",False,0.002): return False
        return False
    def jaw(command):
        s = api.state(); c["jaw_intent"] = command; save()
        for k in range(2):
            if api.state()["budgets"]["jev_remaining"] < 1 or api.state()["budgets"]["native_steps_remaining"] < 3: return False
