    if c["phase"] == "releasing" and api.state()["last_gripper_command"] == "open": c["phase"] = "released"; save()
    if c["phase"] == "closing" and api.state()["last_gripper_command"] == "close": c["phase"] = "testing"; save()
    if c["phase"] == "done" and api.state()["frame_id"] != c["final"]["samples"][-1]["frame"]: c["phase"] = "released"; save()
    if c["phase"] == "survey":
        fields = dict(patch_fields); fields.update({"model":["rigid_box_into_open_bowl","unsupported","unknown"],"support":["resting_on_table","unknown"],"quad":{"type":["array","null"],"items":pixel,"minItems":4,"maxItems":4}})
        for attempt in range(2):
            r = ask("Interpret the runtime user instruction and identify its movable item and receiving bowl. model must match observable rigid rectangular package into an open bowl. Request tight regions top on package top interior and table on adjacent bare support, explicit camera/box/stride=4. Return camera and quad: four genuinely visible top vertices in cyclic order; plane-ray intersections will replace boundary depth. support=resting_on_table only with visible side/support evidence. "+bowl_request+" Also provide identity, persistent interior print-feature definition, measured mark, and textured polygon in camera. Null means missing; on retry use distinct usable samples or the other view.",fields,{"attempt":attempt})
            if r is None: continue
