            v = rays(p["camera"],p["quad"],top)
            if v is None: continue
            n = np.asarray(top["coefficients"][:3]); nt = np.asarray(table["coefficients"][:3]); center = np.mean(v,axis=0); u = max(0.001,top["rms_m"],table["rms_m"]); h = float((np.dot(nt,center)+table["coefficients"][3])/max(0.01,float(np.dot(nt,n))))
            d,e = v[1]-v[0],v[3]-v[0]; L,W = float(np.linalg.norm(d)),float(np.linalg.norm(e)); rectangular = float(np.linalg.norm(v[2]-(v[1]+v[3]-v[0])))
