            env = {"points":np.concatenate([v,v-n*h]).tolist(),"u":u}; c["g"] = {"center":center.tolist(),"top":v.tolist(),"normal":n.tolist(),"table":table,"dimensions":[max(L,W),min(L,W),h],"bowl":dest,"u":u,"frame":r["frame_id"]}; c["phase"] = "approach"; newref(r,env); c.pop("partial",None); save(); break
