    g = c["g"]; dest = g["bowl"]
    if c["phase"] == "approach":
        s = api.state(); q = s["tcp_quaternion_xyzw"]; v = np.asarray(g["top"]); center = np.asarray(g["center"]); u = g["u"]; gap = 2*abs(s["gripper_qpos_m"][0]-s["gripper_qpos_m"][1])-s["own_geometry"]["pad_extent_in_tool_m"][1]; R = geo.rotation(q); width = float(np.ptp(v @ R[:,1]))
        if width+2*u+0.001 >= gap: d,e = v[1]-v[0],v[3]-v[0]; axis = d if np.linalg.norm(d)<np.linalg.norm(e) else e; yaw = math.atan2(axis[1],axis[0])-math.atan2(R[1,1],R[0,1]); yaw = (yaw+math.pi/2)%math.pi-math.pi/2; q = api.compose(q,[0,0,yaw]); R = geo.rotation(q); width = float(np.ptp(v @ R[:,1]))
        own = s["own_geometry"]; lo,hi = own["finger_low_offset_tool_m"],own["finger_high_offset_tool_m"]; offsets = np.asarray([[x,y,z] for x in [lo[0],hi[0]] for y in [lo[1],hi[1]] for z in [lo[2],hi[2]]])-np.asarray(own["pad_center_in_tool_m"])
        fmin = float(np.min((offsets @ R.T)[:,2])); ph = float(np.dot(np.abs(R[2]),own["pad_extent_in_tool_m"])/2); tablez = center[2]-g["dimensions"][2]*g["normal"][2]
